-- Syllabus accountability: a student's own work, read and tagged to the
-- official syllabus dot points, scored into a mastery map that Arcad plans
-- sessions from. See shared/mastery.ts and lib/work-tagging.ts.

-- Official subject matter dot points, shared by every student. Seeded below
-- from shared/syllabus/*.json by scripts/syllabus-seed.mjs.
CREATE TABLE syllabus_points (
  id TEXT PRIMARY KEY,
  syllabus TEXT NOT NULL,
  unit INTEGER NOT NULL,
  unit_title TEXT NOT NULL,
  topic INTEGER NOT NULL,
  topic_title TEXT NOT NULL,
  subtopic TEXT NOT NULL,
  text TEXT NOT NULL,
  -- The sub-topic's teaching hours spread over its dot points.
  hours REAL NOT NULL DEFAULT 1,
  position INTEGER NOT NULL
);
CREATE INDEX syllabus_points_syllabus_idx ON syllabus_points (syllabus, position);

-- Which shared syllabus a student's subject follows, if any.
ALTER TABLE subjects ADD COLUMN syllabus TEXT;

-- One row per piece of work brought in. What was read from it is kept; the
-- file itself only when the student chose to keep it.
CREATE TABLE work_items (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  subject_id TEXT NOT NULL REFERENCES subjects(id) ON DELETE CASCADE,
  -- upload | scan
  source TEXT NOT NULL DEFAULT 'upload',
  filename TEXT NOT NULL,
  content_type TEXT NOT NULL,
  pages INTEGER NOT NULL DEFAULT 1,
  transcript TEXT NOT NULL DEFAULT '',
  -- Set when the student fixed a misread transcript.
  transcript_edited INTEGER NOT NULL DEFAULT 0,
  storage_key TEXT,
  -- read | unread (the model couldn't read it) | checked (check-in done)
  status TEXT NOT NULL DEFAULT 'read',
  prompt_version TEXT NOT NULL,
  model TEXT,
  ms INTEGER,
  created_at INTEGER NOT NULL DEFAULT (unixepoch() * 1000)
);
CREATE INDEX work_items_user_subject_idx ON work_items (user_id, subject_id, created_at);

-- Which dot points a piece of work covered, and how well.
CREATE TABLE work_tags (
  work_item_id TEXT NOT NULL REFERENCES work_items(id) ON DELETE CASCADE,
  point_id TEXT NOT NULL REFERENCES syllabus_points(id),
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  -- 0-100, from the model's marking. NULL for a tag the student added.
  quality INTEGER,
  questions INTEGER NOT NULL DEFAULT 1,
  evidence TEXT NOT NULL DEFAULT '',
  -- 1-5 from the check-in.
  confidence INTEGER,
  -- ai (not checked yet) | confirmed | removed | added. Removed rows stay,
  -- so corrections can be counted.
  state TEXT NOT NULL DEFAULT 'ai',
  prompt_version TEXT NOT NULL,
  created_at INTEGER NOT NULL DEFAULT (unixepoch() * 1000),
  PRIMARY KEY (work_item_id, point_id)
);
CREATE INDEX work_tags_user_point_idx ON work_tags (user_id, point_id);

-- Real marks, for recalibrating the points they covered.
CREATE TABLE results (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  subject_id TEXT NOT NULL REFERENCES subjects(id) ON DELETE CASCADE,
  assessment_id TEXT REFERENCES subject_assessments(id) ON DELETE SET NULL,
  title TEXT NOT NULL,
  mark REAL NOT NULL,
  max_mark REAL NOT NULL,
  taken_on TEXT NOT NULL,
  -- JSON array of syllabus point ids.
  point_ids TEXT NOT NULL DEFAULT '[]',
  created_at INTEGER NOT NULL DEFAULT (unixepoch() * 1000)
);
CREATE INDEX results_user_subject_idx ON results (user_id, subject_id, taken_on);

-- Cached score per point, recomputed when work, a check-in or a mark lands.
CREATE TABLE mastery (
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  point_id TEXT NOT NULL REFERENCES syllabus_points(id),
  score REAL NOT NULL DEFAULT 0,
  q REAL NOT NULL DEFAULT 0,
  c REAL NOT NULL DEFAULT 0,
  r REAL,
  e REAL NOT NULL DEFAULT 0,
  decay REAL NOT NULL DEFAULT 1,
  band TEXT NOT NULL DEFAULT 'none',
  reason TEXT,
  works INTEGER NOT NULL DEFAULT 0,
  last_work_at INTEGER,
  snoozed_until INTEGER,
  covered_elsewhere INTEGER NOT NULL DEFAULT 0,
  updated_at INTEGER NOT NULL DEFAULT (unixepoch() * 1000),
  PRIMARY KEY (user_id, point_id)
);

